mapper.select:
SELECT conversation_id, user_id_1, user_id_2,
       last_message_id, last_message_time, create_time, update_time
FROM conversations
WHERE (user_id_1 = #{userId} OR user_id_2 = #{userId})
  AND last_message_id IS NOT NULL

    AND (last_message_time < #{cursorLastMessageTime}
         OR (last_message_time = #{cursorLastMessageTime}
             AND conversation_id < #{cursorConversationId}))

ORDER BY last_message_time DESC, conversation_id DESC
LIMIT #{limit}
